#[test]
fn negate() {
    assert_eq!(
        HardMediumSoftDecimalScore::new(d("4.0"), d("25.0"), d("-5.0")).neg(),
        HardMediumSoftDecimalScore::new(d("-4.0"), d("-25.0"), d("5.0"))
    );
    assert_eq!(
        HardMediumSoftDecimalScore::new(d("-4.0"), d("3.0"), d("5.0")).neg(),
        HardMediumSoftDecimalScore::new(d("4.0"), d("-3.0"), d("-5.0"))
    );
}

#[test]
fn abs() {
    assert_eq!(
        HardMediumSoftDecimalScore::new(d("4.0"), d("25.0"), d("5.0")).abs(),
        HardMediumSoftDecimalScore::new(d("4.0"), d("25.0"), d("5.0"))
    );
    assert_eq!(
        HardMediumSoftDecimalScore::new(d("4.0"), d("25.0"), d("-5.0")).abs(),
        HardMediumSoftDecimalScore::new(d("4.0"), d("25.0"), d("5.0"))
    );
    assert_eq!(
        HardMediumSoftDecimalScore::new(d("-4.0"), d("3.0"), d("5.0")).abs(),
        HardMediumSoftDecimalScore::new(d("4.0"), d("3.0"), d("5.0"))
    );
    assert_eq!(
        HardMediumSoftDecimalScore::new(d("-4.0"), d("-3.0"), d("-5.0")).abs(),
        HardMediumSoftDecimalScore::new(d("4.0"), d("3.0"), d("5.0"))
    );
}

#[test]
fn zero() {
    assert_eq!(
        HardMediumSoftDecimalScore::ZERO,
        HardMediumSoftDecimalScore::new(d("0"), d("0"), d("0"))
    );
    assert!(HardMediumSoftDecimalScore::new(d("0"), d("0"), d("0")).is_zero());
    assert!(!HardMediumSoftDecimalScore::new(d("0"), d("0"), d("1")).is_zero());
}

#[test]
fn equals_and_hash_code() {
    equal(&[
        HardMediumSoftDecimalScore::new(d("-10.0"), d("3.0"), d("-200.0")),
        HardMediumSoftDecimalScore::new(d("-10.0"), d("3.0"), d("-200.0")),
        HardMediumSoftDecimalScore::new(d("-10.000"), d("3.000"), d("-200.000")),
    ]);
    equal(&[
        HardMediumSoftDecimalScore::from_parts(-1, [d("-10.0"), d("3.0"), d("-200.0")]),
        HardMediumSoftDecimalScore::from_parts(-1, [d("-10.0"), d("3.0"), d("-200.0")]),
    ]);
    distinct(&[
        HardMediumSoftDecimalScore::new(d("-10.0"), d("-30.0"), d("-200.0")),
        HardMediumSoftDecimalScore::new(d("-30.0"), d("-30.0"), d("-200.0")),
        HardMediumSoftDecimalScore::new(d("-10.0"), d("-10.0"), d("-200.0")),
        HardMediumSoftDecimalScore::new(d("-10.0"), d("-30.0"), d("-400.0")),
        HardMediumSoftDecimalScore::new(d("-10.0"), d("-400.0"), d("-30.0")),
        HardMediumSoftDecimalScore::from_parts(-1, [d("-10.0"), d("-30.0"), d("-200.0")]),
    ]);
}

